    /** BPE on one chunk. With `trace`, it also returns the state after each merge. */
    encodeChunk(chunk, trace) {
      let ids = Array.from(utf8Encoder.encode(chunk));
      const steps = trace ? [{ ids: ids.slice(), merge: null }] : null;
