    decode(ids) {
      const parts = ids.filter((id) => !this.isSpecial(id)).map((id) => this.bytes[id]);
      const total = parts.reduce((n, p) => n + p.length, 0);
      const joined = new Uint8Array(total);
      let offset = 0;
      for (const p of parts) {
        joined.set(p, offset);
        offset += p.length;
