    }
  }

  function completeUtf8Length(bytes) {
    // Find the lead byte of the last character, then check if all its bytes are here.
    let i = bytes.length - 1;
    while (i >= 0 && (bytes[i] & 0xc0) === 0x80 && bytes.length - i < 4) i--;
