  function softmax(values) {
    let max = -Infinity;
    for (const v of values) if (v > max) max = v;
    const out = new Float64Array(values.length);
    let sum = 0;
    for (let i = 0; i < values.length; i++) {
      out[i] = values[i] === -Infinity ? 0 : Math.exp(values[i] - max);
      sum += out[i];
