            for (let i = 0; i < hd; i++) dot += q[h * hd + i] * key[g * hd + i];
            s[t] = dot * scale;
          }
          const p = softmax(s);
          for (let t = 0; t <= pos; t++) {
            const value = cache.values[l][t];
            for (let i = 0; i < hd; i++) mixed[h * hd + i] += p[t] * value[g * hd + i];
          }
          scores.push(s);
          weights.push(p);
