      const down = this.layers[layer].down;
      const effects = [];
      for (let n = 0; n < c.hidden_dim; n++) {
        const w = new Float64Array(c.dim);
        for (let d = 0; d < c.dim; d++) w[d] = down[d * c.hidden_dim + n] * this.finalNorm[d];
