    const rec = { raw, modelProbs, afterPenalty, penalized, greedy: settings.temperature === 0 };

    if (rec.greedy) {
      let best = 0;
      for (let i = 1; i < V; i++) if (z[i] > z[best]) best = i;
      const probs = new Float64Array(V);
      probs[best] = 1;
