const tok = m.tokenizer;
const L = (id) => JSON.stringify(tok.label(id));
function show(q, opts) {
  const t0 = Date.now();
  const run = E.simulate(m, q, opts);
  const ms = Date.now() - t0;
  console.log(`\n=== ${q}  (${ms} ms)  prompt=${run.prompt.ids.length} tokens -> ${JSON.stringify(run.text)} finish=${JSON.stringify(run.finish)}`);
  for (const p of run.passes) {
    const d = p.draw;
    const eot = tok.special["<|eot_id|>"];
    const top = E.topIndices(d.modelProbs, 3).map(i => `${L(i)}:${d.modelProbs[i].toFixed(3)}`).join(" ");
    console.log(`pass ${p.index} ${p.kind.padEnd(7)} chose ${L(p.token).padEnd(18)} p_model=${d.modelProbs[p.token].toFixed(3)} p_final=${d.probs[p.token].toFixed(3)} P(eot)=${d.modelProbs[eot].toFixed(3)} kept=${d.keptCount} | ${top}`);
  }
  return run;
}
let run = show("What does the cat eat?", { temperature: 0.6, topP: 0.9 });
