const toks = run.tokens;
for (const p of run.passes.slice(0, 4)) {
  const rec = p.positions[p.positions.length - 1];
  console.log(`\n-- pass ${p.index}: query pos ${rec.pos} token ${L(rec.tokenId)} (predicts ${L(p.token)})`);
  rec.layers.forEach((Lr, l) => {
    const heads = Lr.weights.map((w, h) => {
      const top = E.topIndices(w, 2).map(i => `${L(toks[i].id)}@${i}:${w[i].toFixed(2)}`).join(" ");
      return `h${h}[${top}]`;
    }).join("  ");
    const lens = E.topIndices(p.lens[l].afterMlp, 2).map(i => `${L(i)}:${p.lens[l].afterMlp[i].toFixed(2)}`).join(" ");
    console.log(`L${l}: ${heads}\n     lens after block: ${lens}   |attn|=${E.norm2(Lr.attnOut).toFixed(2)} |mlp|=${E.norm2(Lr.mlpOut).toFixed(2)} |resid|=${E.norm2(Lr.residOut).toFixed(2)}`);
  });
}
show("Tell me a fact.", { temperature: 0.6, topP: 0.9, seed: 1 });
show("Tell me a fact.", { temperature: 0.6, topP: 0.9, seed: 2 });
show("Pick an animal.", { temperature: 0.6, topP: 0.9, seed: 3 });
show("What does the zebra eat?", { temperature: 0.6, topP: 0.9 });
show("Hello, how are you today?", { temperature: 0.6, topP: 0.9 });
show("Tell me about the owl.", { temperature: 1.5, topP: 1, seed: 5 });
show("Tell me about the owl.", { temperature: 0.6, topP: 0.9, repetitionPenalty: 1.3 });
show("What is the capital of France?", { temperature: 0.6, topP: 0.9 });
// neuron effects
const eff = m.neuronEffects(3);
const rec = run.passes[0].positions.at(-1).layers[3];
const topN = E.topIndices(rec.act.map(Math.abs), 5);
console.log("\nlayer 3 top neurons at last prompt pos:", topN.map(n => `${n}:${rec.act[n].toFixed(2)} promotes ${eff[n].promotes.map(L).join(",")}`).join(" | "));
const t0 = Date.now(); for (let l = 0; l < 4; l++) m.neuronEffects(l); console.log("neuron effects ms", Date.now() - t0);
EOF
