function readGrid(pos, fedPass, step) {
  const run = state.run;
  const passes = [];
  for (let p = fedPass; p < run.passes.length; p++) passes.push(p);
  const currentPass = step.type === "finish" ? run.passes.length - 1 : step.pass ?? -1;
  const currentOrder = stageOrder(step.type, step.layer);
  const visible = (p, l) => step.type === "finish" || p < currentPass || (p === currentPass && currentOrder >= stageOrder("attn", l));
  const grid = el("div", { class: "readgrid", style: { gridTemplateColumns: `auto repeat(${passes.length}, 18px)` } });
  grid.append(el("span", { class: "rl" }, "written by pass"));
  for (const p of passes) {
    const token = run.passes[p].token;
    grid.append(el("span", { class: "colhead is-output", title: `Pass ${p + 1} wrote ${tok.label(token)}` }, plainLabel(token)));
  }
  for (let l = 0; l < L; l++) {
    grid.append(el("span", { class: "rl" }, `layer ${l + 1}`));
    for (const p of passes) {
      const queries = run.passes[p].positions.filter((r) => r.pos > pos);
      let best = 0;
      let bestHead = 0;
      for (const r of queries) {
        r.layers[l].weights.forEach((w, h) => { if (w[pos] > best) { best = w[pos]; bestHead = h; } });
      }
      const show = queries.length && visible(p, l);
      grid.append(el("span", {
        class: "cell",
        style: show ? { background: css(ramp(best)) } : null,
        title: show ? `Pass ${p + 1}, layer ${l + 1}: up to ${fmtPct(best)} of the attention (head ${bestHead + 1})` : queries.length ? "not yet" : "no later query in this pass",
      }));
    }
  }
  return el("div", { style: { marginTop: "14px" } },
    figLabel("How much later queries read this token", "max over heads · columns: the token that each pass wrote"),
    grid);
}

input.new_string:
/** Every later position that read this token, with its strongest attention weight per layer. */
function readGrid(pos, step) {
  const run = state.run;
  const P = run.prompt.ids.length;
  const passOf = (q) => (q < P ? 0 : q - P + 1);
  const fedCount = run.passes[run.passes.length - 1].cacheLength;
  const readers = [];
  for (let q = pos + 1; q < fedCount; q++) readers.push(run.passes[passOf(q)].positions.find((r) => r.pos === q));
  if (!readers.length) return null;
  const currentPass = step.type === "finish" ? Infinity : step.pass ?? -1;
  const currentOrder = stageOrder(step.type, step.layer);
  const visible = (q, l) => {
    const p = passOf(q);
    return p < currentPass || (p === currentPass && currentOrder >= stageOrder("attn", l));
  };
  const grid = el("div", { class: "readgrid", style: { gridTemplateColumns: `auto repeat(${readers.length}, 16px)` } });
  grid.append(el("span", { class: "rl" }, "reader"));
  for (const r of readers) {
    const t = run.tokens[r.pos];
    grid.append(el("span", { class: `colhead${t.origin === "generated" ? " is-output" : ""}`, title: `Position ${r.pos}: ${tok.label(r.tokenId)}` }, plainLabel(r.tokenId)));
  }
  for (let l = 0; l < L; l++) {
    grid.append(el("span", { class: "rl" }, `layer ${l + 1}`));
    for (const r of readers) {
      let best = 0;
      let bestHead = 0;
      r.layers[l].weights.forEach((w, h) => { if (w[pos] > best) { best = w[pos]; bestHead = h; } });
      const show = visible(r.pos, l);
      grid.append(el("span", {
        class: "cell",
        style: show ? { background: css(ramp(best)) } : null,
        title: show ? `${tok.label(r.tokenId)} at position ${r.pos}, layer ${l + 1}: ${fmtPct(best)} of head ${bestHead + 1}` : "not computed yet",
      }));
    }
  }
  return el("div", { style: { marginTop: "14px" } },
    figLabel("How much each later token reads this one", "strongest head per layer · empty cells are not computed yet"),
    grid);
}

